#!/usr/bin/env bash
# Connects Dev Files to the Releases page: "Publish" now validates every
# .py/.html/.json file under agent/ + service_files/ BEFORE doing
# anything, and only if all of them pass does it rebuild the served
# tarball AND record a new, permanent, checksummed AgentRelease — visible
# on the Releases page in its own "Agent releases" section, alongside
# Kiosk Application packages.
#
# This is a versioned audit trail/archive, not a deployment mechanism —
# there's still no remote Agent self-update channel (an already-enrolled
# kiosk needs a manual reinstall to pick up any Agent change, same as
# every prior agent-side push this session). What's new is that every
# Agent publish now has a permanent record: who published it, when, its
# exact checksum, and a downloadable copy of that exact build - the same
# kind of history the Kiosk Application's releases have always had.
#
# Also corrects an inaccurate warning I'd written earlier: editing an
# agent/*.py file DOES briefly restart this Admin Panel server (Werkzeug's
# reloader watches all .py files broadly, not just imported ones) - I'd
# said it "can't affect anything running right now", which wasn't quite
# right. The important part still holds: since agent/ code is never
# actually imported by the Admin Panel, even a broken file there just
# causes that brief restart blip and the server comes back up fine - only
# app/*.py can make the restart itself fail. The warning banners now say
# this accurately.
#
# Tested against a live server before this was shipped: corrupted a file
# directly on disk (bypassing the editor's own save-check) and confirmed
# Publish independently caught it, named the exact file/line/reason, and
# created zero release records; fixed it and published successfully,
# confirmed it appeared on the Releases page with a checksum that matched
# an independent sha256sum of the archived file; confirmed the download
# route serves back that exact build; confirmed publishing the same
# version twice is rejected as a duplicate.
#
# Includes a database migration (new agent_releases table).
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app migrations requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/dev_files" "backups/$TS/templates/releases"
cp app/models.py "backups/$TS/models.py.bak" 2>/dev/null || true
cp app/blueprints/dev_files.py "backups/$TS/dev_files.py.bak" 2>/dev/null || true
cp app/blueprints/releases.py "backups/$TS/releases.py.bak" 2>/dev/null || true
cp app/templates/dev_files/index.html "backups/$TS/templates/dev_files/index.html.bak" 2>/dev/null || true
cp app/templates/dev_files/edit.html "backups/$TS/templates/dev_files/edit.html.bak" 2>/dev/null || true
cp app/templates/releases/list.html "backups/$TS/templates/releases/list.html.bak" 2>/dev/null || true
cp -r admin_panel.db "backups/$TS/admin_panel.db.bak" 2>/dev/null || true
echo "==> Backed up existing files (incl. a DB copy - this push includes a migration) to backups/$TS/"

echo "==> Writing app/models.py"
base64 -d > app/models.py << 'MODELS_PY_B64'

MODELS_PY_B64

echo "==> Writing app/blueprints/dev_files.py"
base64 -d > app/blueprints/dev_files.py << 'DEV_FILES_PY_B64'

DEV_FILES_PY_B64

echo "==> Writing app/blueprints/releases.py"
base64 -d > app/blueprints/releases.py << 'RELEASES_PY_B64'

RELEASES_PY_B64

echo "==> Writing app/templates/dev_files/index.html"
base64 -d > app/templates/dev_files/index.html << 'DEV_INDEX_HTML_B64'

DEV_INDEX_HTML_B64

echo "==> Writing app/templates/dev_files/edit.html"
base64 -d > app/templates/dev_files/edit.html << 'DEV_EDIT_HTML_B64'

DEV_EDIT_HTML_B64

echo "==> Writing app/templates/releases/list.html"
base64 -d > app/templates/releases/list.html << 'RELEASES_LIST_HTML_B64'

RELEASES_LIST_HTML_B64

echo "==> Writing new Alembic migration (agent_releases)"
base64 -d > migrations/versions/c6f1a9e3d7b2_add_agent_releases.py << 'MIGRATION_PY_B64'

MIGRATION_PY_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/models.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/dev_files.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/releases.py').read())"
python3 -c "import ast; ast.parse(open('migrations/versions/c6f1a9e3d7b2_add_agent_releases.py').read())"
echo "    all Python files: syntax OK"

echo ""
echo "==> Applying database migration (agent_releases table)"
source venv/bin/activate
FLASK_APP=run.py python -m flask db upgrade

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Dev Files' Publish now has version + release notes fields. It"
echo "checks every shipped .py/.html/.json file first - if anything fails,"
echo "nothing changes and you'll see exactly which file and why."
echo ""
echo "On success: the tarball is rebuilt AND a new entry appears on the"
echo "Releases page under 'Agent releases', with a checksum and a"
echo "download link for that exact build."
echo ""
echo "Still no remote Agent self-update channel - already-enrolled kiosks"
echo "need a reinstall to pick up any Agent change, same as always."
echo "==================================================================="
